// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/audit-logs", wrapper.ListAuditLogs)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/audit-logs/{id}", wrapper.GetAuditLog)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/oauth/token", wrapper.RefreshToken)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/roles", wrapper.ListRoles)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/roles", wrapper.CreateRole)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/roles/{id}", wrapper.DeleteRole)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/roles/{id}", wrapper.GetRole)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/v1/roles/{id}", wrapper.UpdateRole)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/sessions", wrapper.CreateSession)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/sessions/current", wrapper.DeleteCurrentSession)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/staff", wrapper.ListStaff)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/staff-invitations", wrapper.ListStaffInvitations)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/staff-invitations", wrapper.CreateStaffInvitation)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/staff-invitations/{id}", wrapper.RevokeStaffInvitation)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/staff-invitations/{id}", wrapper.GetStaffInvitation)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/staff-invitations/acceptance", wrapper.AcceptStaffInvitation)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/staff/{id}", wrapper.RemoveStaff)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/staff/{id}", wrapper.GetStaff)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/v1/staff/{id}", wrapper.UpdateStaff)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/staff/me", wrapper.GetCurrentStaff)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/staff/me/step-up", wrapper.CreateStepUp)

	return m
}

